"""Manim templates: no AI-authored or user-supplied code is evaluated."""
import math
from .models import Topic


def make_manim(topic: Topic, p: dict[str, float]) -> tuple[str, str]:
    # repr(float) ensures interpolated values are numeric literals, never executable code.
    numbers = {key: repr(float(value)) for key, value in p.items()}
    header = '''from manim import *
import numpy as np

# Generated by PhysicsSolutionAgent from validated numeric parameters.
# Rendering requires Manim Community Edition and its OS dependencies.
'''
    if topic == 'spring':
        return header + f'''
class SpringScene(Scene):
    def construct(self):
        mass, k, amp = {numbers['mass']}, {numbers['k']}, {numbers['amplitude']}
        omega = (k / mass) ** 0.5
        title = Text("Simple Harmonic Motion", font_size=35).to_edge(UP)
        floor = Line(LEFT * 5 + DOWN, RIGHT * 5 + DOWN, color=GRAY_B)
        wall = Rectangle(width=.18, height=1.8, color=GRAY_B, fill_opacity=1).move_to(LEFT*4 + DOWN*.15)
        x = ValueTracker(amp)
        block = Square(side_length=.9, color=BLUE_D, fill_color=BLUE_D, fill_opacity=.95)
        block.add_updater(lambda obj: obj.move_to(RIGHT*(x.get_value()*6) + DOWN*.55))
        spring = always_redraw(lambda: ParametricFunction(
            lambda t: np.array([-3.9 + (3.45+x.get_value()*6)*t,
                                  -.55 + .17*np.sin(24*np.pi*t), 0]),
            t_range=[0,1], color=YELLOW, stroke_width=3))
        equation = MathTex(r"x(t)=A\\cos(\\omega t)").to_edge(DOWN)
        self.add(title, floor, wall, spring, block, equation)
        self.play(UpdateFromAlphaFunc(x, lambda tracker, a: tracker.set_value(amp*np.cos(2*np.pi*a))),
                  run_time=4, rate_func=linear)
        self.wait(.5)
''' , 'SpringScene'
    if topic == 'projectile':
        return header + f'''
class ProjectileScene(Scene):
    def construct(self):
        speed, angle = {numbers['speed']}, {numbers['angle_deg']}
        theta = np.deg2rad(angle)
        gravity = 9.81
        duration = 2*speed*np.sin(theta)/gravity
        distance = speed*np.cos(theta)*duration
        height = (speed*np.sin(theta))**2/(2*gravity)
        title = Text("Projectile Motion", font_size=35).to_edge(UP)
        axes = Axes(x_range=[0, max(distance*1.12, 1), max(distance/4, 1)],
                    y_range=[0, max(height*1.3, 1), max(height/4, 1)],
                    x_length=9, y_length=4.7, tips=False).shift(DOWN*.5)
        point = ValueTracker(0)
        def trajectory(t):
            xx = speed*np.cos(theta)*t
            yy = speed*np.sin(theta)*t-.5*gravity*t*t
            return axes.c2p(xx, max(0,yy))
        curve = ParametricFunction(lambda u: trajectory(u), t_range=[0,duration], color=BLUE_C)
        ball = always_redraw(lambda: Dot(trajectory(point.get_value()), radius=.12, color=YELLOW))
        self.add(title, axes, curve, ball)
        self.play(point.animate.set_value(duration), run_time=4, rate_func=linear)
        self.wait(.5)
''' , 'ProjectileScene'
    if topic == 'incline':
        return header + f'''
class InclineScene(Scene):
    def construct(self):
        angle_deg, t_end = {numbers['angle_deg']}, {numbers['time']}
        angle = np.deg2rad(angle_deg)
        top = np.array([-3.5, 1.5, 0])
        foot = np.array([3, 1.5-6.5*np.tan(angle), 0])
        # Keep drawing within the visible 16:9 frame even at steep angles.
        drop = min(3.2, 6.5*np.tan(angle))
        foot = np.array([-3.5 + drop/max(np.tan(angle), .01), 1.5-drop, 0])
        ramp = Line(top, foot, color=GRAY_B, stroke_width=8)
        title = Text("Frictionless Inclined Plane", font_size=34).to_edge(UP)
        progress = ValueTracker(0)
        block = always_redraw(lambda: Square(side_length=.6, fill_color=BLUE_C, fill_opacity=.95,
            color=BLUE_C).move_to(top*(1-progress.get_value()) + foot*progress.get_value() + UP*.35))
        formula = MathTex(r"a=g\\sin(\\theta)").to_edge(DOWN)
        self.add(title, ramp, block, formula)
        self.play(progress.animate.set_value(.95), run_time=4, rate_func=rate_functions.ease_in_quad)
        self.wait(.5)
''' , 'InclineScene'
    if topic == 'pendulum':
        return header + f'''
class PendulumScene(Scene):
    def construct(self):
        length, angle = {numbers['length']}, {numbers['angle_deg']}
        pivot = UP*1.7
        theta = ValueTracker(np.deg2rad(angle))
        rope = always_redraw(lambda: Line(pivot, pivot +
            np.array([2.8*np.sin(theta.get_value()), -2.8*np.cos(theta.get_value()), 0]), color=GRAY_B))
        bob = always_redraw(lambda: Dot(rope.get_end(), radius=.22, color=BLUE_C))
        anchor = Dot(pivot, radius=.09, color=YELLOW)
        title = Text("Simple Pendulum", font_size=35).to_edge(UP)
        formula = MathTex(r"T=2\\pi\\sqrt{{L/g}}").to_edge(DOWN)
        self.add(title, anchor, rope, bob, formula)
        self.play(UpdateFromAlphaFunc(theta, lambda tracker, a: tracker.set_value(
            np.deg2rad(angle)*np.cos(4*np.pi*a))), run_time=5, rate_func=linear)
        self.wait(.5)
''' , 'PendulumScene'
    raise ValueError('Unsupported topic.')
